def choose_move(observation):
    gx = observation.get('grid_width', 0)
    gy = observation.get('grid_height', 0)

    pos = observation.get('self_position', {}) or {}
    opp = observation.get('opponent_position', {}) or {}

    x = pos.get('x', 0)
    y = pos.get('y', 0)

    # Gather potential targets: resources or obstacles as simple heuristics
    targets = []
    for key in ('resources', 'obstacles'):
        items = observation.get(key, [])
        if isinstance(items, list):
            for it in items:
                if isinstance(it, dict):
                    tx = it.get('x')
                    ty = it.get('y')
                    if tx is not None and ty is not None:
                        targets.append((tx, ty))

    # Move toward the closest target if any
    if targets:
        best = None
        best_dist = 10**9
        for tx, ty in targets:
            dx = tx - x
            dy = ty - y
            dist = abs(dx) + abs(dy)
            if dist < best_dist:
                best_dist = dist
                best = (dx, dy)
        if best is not None:
            dx, dy = best
            move_x = (dx > 0) - (dx < 0)
            move_y = (dy > 0) - (dy < 0)
            return [move_x, move_y]

    # Otherwise, move toward center of map (0,0) as a deterministic fallback
    dx = -x
    dy = -y
    move_x = (dx > 0) - (dx < 0)
    move_y = (dy > 0) - (dy < 0)

    # Clamp to stay within grid if width/height known
    if gx:
        nx = x + move_x
        if nx < 0:
            move_x = 0
        elif nx >= gx:
            move_x = 0
    if gy:
        ny = y + move_y
        if ny < 0:
            move_y = 0
        elif ny >= gy:
            move_y = 0

    return [move_x, move_y]
